// Requirements:-

// 1. Fix the filter so it displays the correct orders.
// 2. Do not mutate the existing products array or product objects.
// 3. Accept an order only if its status is Pending.
// 4. Check product stock before accepting an order.
// 5. Never allow stock to become negative.
// 6. Reduce stock only when an order is successfully accepted.
// 7. Reject an order only if its status is Pending.
// 8. Prevent processing an order more than once.
// 9. Display pending, accepted, and rejected order counts.
// 10. Display total remaining stock.
// 11. Show a message when no orders match the filter.
// 12. Handle invalid order IDs safely.

// ===========================================
//          Code After Solved Bugs
// ===========================================

// ## E-commerce Order Management Dashboard

import { useState } from "react";
function Task11() {
  const [products, setProducts] = useState([
    { id: 1, name: "Laptop", stock: 5 },
    { id: 2, name: "Mobile", stock: 3 },
    { id: 3, name: "Headphones", stock: 8 }
  ]);

  const [orders, setOrders] = useState([
    { id: 1, customer: "Rahul", productId: 1, quantity: 2, status: "Pending" },
    { id: 2, customer: "Priya", productId: 2, quantity: 4, status: "Pending" },
    { id: 3, customer: "Arjun", productId: 3, quantity: 2, status: "Accepted" },
    { id: 4, customer: "Sneha", productId: 1, quantity: 1, status: "Pending" }
  ]);

  const [filter, setFilter] = useState("All");

  function acceptOrder(orderId) {
    const order = orders.find(item => item.id === orderId);
    if(!order){
        return;
    }
    const updatedProducts = products.map(product => {
        if (product.id === order.productId) {
            if(product.stock<order.quantity){
                alert("max no.of qunatity exceeded")
                return {...product};
            }
            const updatedOrders = orders.map(item => {
            if (item.id === orderId) {
                if(item.status==="Pending"){
                    return { ...item, status: "Accepted", quantity:0};
                }
                alert("already action Proccessed")
                return{...item}
            }
            return item;
            });
            setOrders(updatedOrders);
            return{...product,stock:product.stock-order.quantity}
        }
        return product;
    });

    setProducts(updatedProducts);
  }

  function rejectOrder(orderId) {
    const updatedOrders = orders.map(item => {
      if (item.id === orderId) {
        if(item.status==="Pending"){
            return { ...item, status: "Rejected" };
        }
        alert("already action Proccessed")
        return{...item}
      }
      return item;
    });

    setOrders(updatedOrders);
  }

  const filteredOrders = orders.filter(order => {
    return filter === "All" || order.status === filter;
  });

  const pendingCount = orders.filter(
    order => order.status === "Pending"
  ).length;

  const totalStock = products.reduce(
    (total, product) => total + product.stock,
    0
  );

  
  const acceptedOrders = orders.filter(
    order => order.status === "Accepted"
  ).length;
  

  const rejectedOrders = orders.filter(
    order => order.status === "Rejected"
  ).length;



  return (
    <div>
      <h2>Order Dashboard</h2>

      <h3>Pending Orders: {pendingCount}</h3>
      <h3>Accepted Orders: {acceptedOrders}</h3>
      <h3>Rejected Orders: {rejectedOrders}</h3>
      <h3>Total Stock: {totalStock}</h3>

      <select value={filter} onChange={e => setFilter(e.target.value)}>
        <option value="All">All</option>
        <option value="Pending">Pending</option>
        <option value="Accepted">Accepted</option>
        <option value="Rejected">Rejected</option>
      </select>

      {filteredOrders.map(order => (
        <div key={order.id}>
          <p>{order.customer}</p>
          <p>{order.status}</p>

          <button onClick={() => acceptOrder(order.id)}>
            Accept
          </button>

          <button onClick={() => rejectOrder(order.id)}>
            Reject
          </button>
        </div>
      ))}
      {/* {console.log(orders)}
      {console.log(products)} */}
    </div>
  );
}

export default Task11;